&lt;p&gt;A = P(1 + r/100)&lt;span style=&quot;position: relative;  line-height: 0; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;n&lt;/span&gt;&lt;/p&gt;

