&lt;p&gt;841/625 = (1 + r/100)&lt;span style=&quot;position: relative; line-height: 0; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 841/625 = (1 + r/100)&lt;span style=&quot;position: relative; line-height: 0; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; (29/25)&lt;span style=&quot;position: relative; line-height: 0; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= (1 + r/100)&lt;span style=&quot;position: relative; line-height: 0; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 26/25 = 1 + r/100&lt;/p&gt;

&lt;p&gt;&amp;rArr; r/100 = 29/25 - 1&lt;/p&gt;

&lt;p&gt;&amp;rArr; r/100 = 4/25&lt;/p&gt;

&lt;p&gt;&amp;rArr; r = 16%&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;there4;&lt;/span&gt; &lt;span style=&quot;font-weight: 700;&quot;&gt;ब्याज की दर 16% है।&lt;/span&gt;&lt;/p&gt;

