		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसमें 195 सदस्य और 8 सहयोगी सदस्य हैं और यह सामान्य सम्मेलन और कार्यकारी बोर्ड द्वारा शासित है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसका मिशन शिक्षा, विज्ञान, संस्कृति, संचार और सूचना के माध्यम से शांति की संस्कृति के निर्माण, गरीबी उन्मूलन, सतत विकास और अंतर-सांस्कृतिक संवाद में योगदान देना है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह मुख्य रूप से वैश्विक प्राथमिकता वाले क्षेत्रों &amp;quot;अफ्रीका&amp;quot; और &amp;quot;लैंगिक समानता&amp;quot; में उद्देश्यों के एक समूह पर केंद्रित है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;u&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;मुख्यालय- पेरिस, फ्रांस&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;महानिदेशक- ऑड्रे अज़ोले&lt;/font&gt;&lt;/font&gt;&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Telnet.&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;p&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Any&lt;strong&gt; application that empowers users to remotely access&lt;/strong&gt; another computer(no matter how far away) is called &lt;strong&gt;remote access.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;Telnet&lt;/strong&gt;&lt;/u&gt; is an application protocol that uses a virtual terminal connection to offer bidirectional interactive text-oriented communication over the Internet.&lt;/li&gt;
	&lt;li&gt;Telnet&amp;nbsp;facilitates&lt;strong&gt; remote login on a computer.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;It also facilitates terminal emulation purposes.&lt;/li&gt;
	&lt;li&gt;Telnet was developed in &lt;strong&gt;1969.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Telnet allows users to execute various application programmes on a distant site and then transport the results back to their local computer.&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;The Hypertext Transfer Protocol (HTTP)&lt;/strong&gt; is the backbone of the &lt;strong&gt;internet&amp;#39;s data transfer.&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;It is a stateless protocol.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Real-Time Protocol (RTP) &lt;/strong&gt;is a protocol designed to handle real-time traffic&lt;strong&gt; (like audio and video)&lt;/strong&gt; of the Internet.&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;File Transfer Protocol&lt;/strong&gt; is a set&amp;nbsp;of rules that govern how computers transfer files from one system to another over the internet&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;color: rgb(37, 37, 37);  &quot;&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;टेलनेट&lt;/strong&gt;&lt;/u&gt; है।&lt;/span&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;कोई भी &lt;strong&gt;एप्लिकेशन जो उपयोगकर्ताओं&lt;/strong&gt; को किसी अन्य कंप्यूटर (चाहे कितनी भी दूर हो) को &lt;strong&gt;दूरस्थ रूप से एक्सेस करने का अधिकार देता है,&lt;/strong&gt; उसे &lt;strong&gt;रिमोट एक्सेस&lt;/strong&gt; कहा जाता है।&lt;/li&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;टेलनेट&lt;/strong&gt;&lt;/u&gt; एक एप्लिकेशन प्रोटोकॉल है जो इंटरनेट पर द्विदिश संवादात्मक पाठ-उन्मुख संचार प्रदान करने के लिए वर्चुअल टर्मिनल कनेक्शन का उपयोग करता है।&lt;/li&gt;
	&lt;li&gt;टेलनेट &lt;strong&gt;कंप्यूटर पर दूरस्थ लॉगिन&lt;/strong&gt; की सुविधा प्रदान करता है।&lt;/li&gt;
	&lt;li&gt;यह टर्मिनल इम्यूलेशन उद्देश्यों को भी सुविधाजनक बनाता है।&lt;/li&gt;
	&lt;li&gt;टेलनेट को &lt;strong&gt;1969&lt;/strong&gt; में विकसित किया गया था।&lt;/li&gt;
	&lt;li&gt;टेलनेट उपयोगकर्ताओं को दूरस्थ साइट पर विभिन्न एप्लिकेशन प्रोग्राम निष्पादित करने की अनुमति देता है और फिर परिणामों को उनके स्थानीय कंप्यूटर पर वापस ले जाता है।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;हाइपरटेक्स्ट ट्रांसफर प्रोटोकॉल (HTTP) इंटरनेट के डेटा ट्रांसफर&lt;/strong&gt; की रीढ़ है।

	&lt;ul&gt;
		&lt;li&gt;यह एक स्टेटलेस प्रोटोकॉल है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;रीयल-टाइम प्रोटोकॉल (RTP) &lt;/strong&gt;इंटरनेट के रीयल-टाइम ट्रैफ़िक&lt;strong&gt; (जैसे ऑडियो और वीडियो) &lt;/strong&gt;को संभालने के लिए डिज़ाइन किया गया एक प्रोटोकॉल है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;फाइल ट्रांसफर प्रोटोकॉल&lt;/strong&gt; नियमों का एक सेट है जो यह नियंत्रित करता है कि कंप्यूटर इंटरनेट पर एक सिस्टम से दूसरे सिस्टम में फाइल कैसे ट्रांसफर करते हैं&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Train is travelling 50% faster than a bus&lt;/p&gt;

&lt;p&gt;Distance between Karnal and Panipat = 75 km&lt;/p&gt;

&lt;p&gt;Time = 12.5 min&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Speed = Distance/Time&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Let the speed of the bus be x km/h&lt;/p&gt;

&lt;p&gt;Then,&lt;/p&gt;

&lt;p&gt;Speed of the train = (150/100)x = (3/2)x km/h&lt;/p&gt;

&lt;p&gt;According to the question&lt;/p&gt;

&lt;p&gt;&amp;rArr; 75/x&amp;nbsp;&lt;span style=&quot; line-height: 115%;  background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&amp;nbsp;&amp;nbsp;&lt;/span&gt;75/(3/2)x = (125/10&amp;nbsp;&amp;times; 60)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 75/x&amp;nbsp;&lt;span style=&quot; line-height: 115%;  background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&amp;nbsp;&amp;nbsp;&lt;/span&gt;50/x = 5/24&lt;/p&gt;

&lt;p&gt;&amp;rArr; 25/x = 5/24&lt;/p&gt;

&lt;p&gt;&amp;rArr; x = (25&amp;nbsp;&amp;times; 24)/5&lt;/p&gt;

&lt;p&gt;&amp;rArr; x = 120 km/h&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; The speed of the bus is 120 km/h.&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/alternate-methord-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Alternate Method&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;The speed of the bus = 2x km/hr&lt;/p&gt;

&lt;p&gt;then, the speed of train = 150% of 2x = 3x km/hr&lt;/p&gt;

&lt;p&gt;let time taken by train and bus each = y hours&lt;/p&gt;

&lt;p&gt;and&lt;/p&gt;

&lt;p&gt;Distance = Speed&amp;nbsp;&amp;times; time&lt;/p&gt;

&lt;p&gt;&amp;rArr; 3x&amp;nbsp;&amp;times; y = 2x&amp;nbsp;&amp;times; (y + 12.5/60)&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;3xy = 2xy + (5/12)x&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;y = 5/12 hours&lt;/p&gt;

&lt;p&gt;and we know, the distance is 75 km.&lt;/p&gt;

&lt;p&gt;So, 3xy = 75&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;3x &amp;times; (5/12) = 75&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;x = 60 km/hr&lt;/p&gt;

&lt;p&gt;So,&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;The speed of Bus = 2x = 2&amp;nbsp;&amp;times; 60 = 120 km/hr&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&lt;span style=&quot;font-weight: bolder;&quot;&gt;दिया गया है:&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;ट्रेन,&amp;nbsp;बस से 50% अधिक तेज चलती है&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;करनाल और पानीपत के बीच दूरी = 75 किमी&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;समय = 12.5 मिनट&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&lt;span style=&quot;font-weight: bolder;&quot;&gt;प्रयुक्त सूत्र:&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;गति = दूरी/समय&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&lt;span style=&quot;font-weight: bolder;&quot;&gt;गणना:&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;मान लीजिए बस की गति x किमी/घंटा है&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;तब,&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;ट्रेन की गति = (150/100)x = (3/2)x किमी/घंटा&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;प्रश्न के अनुसार&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr; 75/x&amp;nbsp;&lt;span style=&quot;line-height: 16.1px; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&lt;/span&gt;&amp;nbsp;75/(3/2)x = (125/10 &amp;times; 60)&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr; 75/x&amp;nbsp;&lt;span style=&quot;line-height: 16.1px; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&lt;/span&gt;&amp;nbsp;50/x = 5/24&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr; 25/x = 5/24&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr; x = (25 &amp;times; 24)/5&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr; x = 120 किमी/घंटा&lt;/p&gt;

&lt;p style=&quot;color: rgb(33, 37, 41);&quot;&gt;&lt;span style=&quot;font-weight: bolder;&quot;&gt;&amp;there4; बस की गति 120 किमी/घंटा है।&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/alternate-methord-image.png&quot; style=&quot;color: rgb(33, 37, 41); font-weight: 700;&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: bolder;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Alternate Method&lt;/u&gt;&lt;/span&gt;&lt;/span&gt; बस की गति = 2x किमी/घंटा&lt;/p&gt;

&lt;p&gt;तब, ट्रेन की गति = 2x का 150% = 3x किमी/घंटा&lt;/p&gt;

&lt;p&gt;ट्रेन और बस द्वारा लिया गया समय = y घंटे&lt;/p&gt;

&lt;p&gt;और&lt;/p&gt;

&lt;p&gt;दूरी = गति &amp;times; समय&lt;/p&gt;

&lt;p&gt;&amp;rArr; 3x &amp;times; y = 2x &amp;times; (y + 12.5/60)&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&lt;/span&gt; 3xy = 2xy + (5/12)x&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&lt;/span&gt; y = 5/12 घंटे&lt;/p&gt;

&lt;p&gt;और हम जानते हैं कि दूरी 75 किमी है।&lt;/p&gt;

&lt;p&gt;अतः, 3xy = 75&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&lt;/span&gt; 3x &amp;times; (5/12) = 75&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;&amp;rArr;&lt;/span&gt; x = 60 किमी/घंटा&lt;/p&gt;

&lt;p&gt;इसलिए,&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;बस की गति = 2x = 2 &amp;times; 60 = 120 किमी/घंटा&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Intelligence quotient&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;A total score resulting from a set of standardized tests or subtests designed to estimate human intelligence is known as an &lt;strong&gt;intelligence quotient (IQ)&lt;/strong&gt;.&lt;/li&gt;
	&lt;li&gt;The psychologist William Stern invented the abbreviation &amp;quot;IQ&amp;quot; for the German term Intelligenzquotient, which he used to describe a scoring procedure for intelligence tests at the University of Breslau that he promoted in a 1912 book.&lt;/li&gt;
	&lt;li&gt;IQ was traditionally calculated by dividing a person&amp;#39;s mental age, as determined by an intelligence test, by the person&amp;#39;s chronological age, both given in years and months.&lt;/li&gt;
	&lt;li&gt;Intelligence test results are assessments of intelligence.&lt;/li&gt;
	&lt;li&gt;Computers&amp;#39; speed, precision, diligence, versatility, and storage capacity are features that have made them so powerful and generally useful.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;strong&gt;​&lt;span style=&quot;&quot;&gt;इन्टेलिजन्स क्वोशन्ट&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;है।&amp;nbsp;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;मानव बुद्धि का अनुमान लगाने के लिए डिज़ाइन किए गए मानकीकृत परीक्षणों या उप-परीक्षणों के एक सेट से उत्पन्न कुल स्कोर को &lt;span style=&quot;&quot;&gt;इन्टेलिजन्स क्वोशन्ट&lt;/span&gt; (IQ) के रूप में जाना जाता है।&lt;/li&gt;
	&lt;li&gt;मनोवैज्ञानिक विलियम स्टर्न ने जर्मन शब्द &lt;span style=&quot;color: rgb(33, 37, 41);  &quot;&gt;इन्टेलिजन्स क्वोशन्ट&lt;/span&gt; के लिए संक्षिप्त नाम &amp;quot;IQ&amp;quot; का आविष्कार किया, जिसका उपयोग उन्होंने ब्रेस्लाउ विश्वविद्यालय में खुफिया परीक्षणों के लिए एक स्कोरिंग प्रक्रिया का वर्णन करने के लिए किया था जिसे उन्होंने 1912 की पुस्तक में प्रचारित किया था।&lt;/li&gt;
	&lt;li&gt;IQ की गणना पारंपरिक रूप से किसी व्यक्ति की मानसिक आयु को विभाजित करके की जाती है, जैसा कि एक बुद्धि परीक्षण द्वारा निर्धारित किया जाता है, व्यक्ति की कालानुक्रमिक आयु, दोनों वर्षों और महीनों में दी जाती है।&lt;/li&gt;
	&lt;li&gt;बुद्धि परीक्षण के परिणाम बुद्धि के आकलन हैं।&lt;/li&gt;
	&lt;li&gt;कंप्यूटर कीस्पीड,एक्यूरेसी, डिलिजेंस, वेर्सटिलिटी और स्टोरेज कैपेसिटी ऐसी विशेषताएं हैं जिन्होंने उन्हें इतना शक्तिशाली और आम तौर पर उपयोगी बना दिया है।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;The number 356yx is divisible by 90&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;For divisibility by 10 the last digit of the number must be 0&lt;/p&gt;

&lt;p&gt;Similarly, for divisibility by 9, sum&amp;nbsp;of digits of that&amp;nbsp;number must be divisible by 9&lt;/p&gt;

&lt;p&gt;Here, 356yx is divisible by 90 .i.e. 356yx is divisible by 9 and 10&amp;nbsp;&lt;/p&gt;

&lt;p&gt;356yx&amp;nbsp;is divisible by 10&amp;nbsp;&lt;/p&gt;

&lt;p&gt;So, the value of x = 0&lt;/p&gt;

&lt;p&gt;Now, 356y0 is divisible by 9&lt;/p&gt;

&lt;p&gt;So, (3 + 5 + 6 + y + 0) = (14 + y) is divisible by 9&lt;/p&gt;

&lt;p&gt;So, the smallest number that should be added to 14 that is also divisible by 9 is 4&lt;/p&gt;

&lt;p&gt;&amp;rArr; y = 4&lt;/p&gt;

&lt;p&gt;Now,&lt;/p&gt;

&lt;p&gt;(y&amp;nbsp;&lt;span style=&quot; line-height: 115%;  background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&amp;nbsp;&lt;/span&gt;&amp;nbsp;x) = (4&amp;nbsp;&lt;span style=&quot; line-height: 115%;  background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&amp;nbsp;&lt;/span&gt;&amp;nbsp;0)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; The required value is 4&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;दिया गया है:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;संख्या 356yx, 90 से विभाज्य है&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;गणना:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;10 से विभाज्य होने के लिए संख्या का अंतिम अंक 0 होना चाहिए।&amp;nbsp;&lt;/p&gt;

&lt;p&gt;इसी प्रकार, 9 से विभाज्यता के लिए, उस संख्या के अंकों का योग 9 से विभाज्य होना चाहिए।&amp;nbsp;&lt;/p&gt;

&lt;p&gt;यहाँ, 356yx, 90 से विभाज्य है अर्थात् 356yx, 9 और 10 से विभाज्य है&lt;/p&gt;

&lt;p&gt;356yx, 10 से विभाज्य है&lt;/p&gt;

&lt;p&gt;इसलिए, x का मान&amp;nbsp;= 0&lt;/p&gt;

&lt;p&gt;अब, 356yx, 9 से विभाज्य है&amp;nbsp;&lt;/p&gt;

&lt;p&gt;इसलिए, (3 + 5 + 6 + y + 0) = (14 + y)&amp;nbsp;9 से विभाज्य है&amp;nbsp;&lt;/p&gt;

&lt;p&gt;इसलिए, वह सबसे छोटी संख्या जिसे 14 में जोड़ा जाना चाहिए ताकि यह&amp;nbsp;9 से विभाज्य हो, वह 4 है।&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; y = 4&lt;/p&gt;

&lt;p&gt;अब,&lt;/p&gt;

&lt;p&gt;(y&amp;nbsp;&lt;span style=&quot;line-height: 16.1px; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&amp;nbsp;&lt;/span&gt;&amp;nbsp;x) = (4&amp;nbsp;&lt;span style=&quot;line-height: 16.1px; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;ndash;&amp;nbsp;&lt;/span&gt;&amp;nbsp;0)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;there4; अभीष्ट मान 4 है।&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Number = 4707&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Concept:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Dividend = Divisor&amp;nbsp;&amp;times; Quotient + Remainder&amp;nbsp;&lt;/p&gt;

&lt;p&gt;LCM = Lowest Common Multiple&amp;nbsp;&lt;/p&gt;

&lt;p&gt;It is the smallest positive number that is divisible by two or more numbers.&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;To find the least number which can be added to 4707 that is exactly divisible by 4, 5, 6 and 8, we need to find the LCM of these 4 numbers.&amp;nbsp;&lt;/p&gt;

&lt;p&gt;LCM of 4, 5, 6 and 8 can be calculated by prime factorization;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;4 = 2&lt;sup&gt;2&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;5 = 5&lt;/p&gt;

&lt;p&gt;6 = 2&amp;nbsp;&amp;times; 3&amp;nbsp;&lt;/p&gt;

&lt;p&gt;8 = 2&lt;sup&gt;3&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; LCM (4, 5, 6, 8) = 2&lt;sup&gt;3&lt;/sup&gt;&amp;nbsp;&amp;times; 3&amp;nbsp;&amp;times; 5 = 120&lt;/p&gt;

&lt;p&gt;When divided&amp;nbsp;4707 by 120, we get&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4707 = 120&amp;nbsp;&amp;times; 39 + 27&amp;nbsp;&lt;/p&gt;

&lt;p&gt;By adding the difference of Divisor and remainder (120 - 27) = 93&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4707 + 93 =&amp;nbsp;120&amp;nbsp;&amp;times; 39 + 27 + 93&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4800 = 120&amp;nbsp;&amp;times; 39 + 120&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4800 = 120 (39 + 1)&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4800 = 120&amp;nbsp;&amp;times; 40&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; The least number that should&amp;nbsp;be added to 4707&amp;nbsp;so that the sum is exactly divisible by 4, 5, 6 and 8 is 93.&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;दिया गया है:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;संख्या = 4707&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;अवधारणा:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;लाभांश = भाजक &amp;times; भागफल + शेष&lt;/p&gt;

&lt;p&gt;लघुत्तम समापवर्तक = सबसे छोटा उभयनिष्ठ गुणक&lt;/p&gt;

&lt;p&gt;यह सबसे छोटी धनात्मक संख्या है जो दो या दो से अधिक संख्याओं से विभाजित&amp;nbsp;होती है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;4707 में जोड़ी जा सकने वाली वह छोटी से छोटी संख्या ज्ञात करने के लिए जो 4, 5, 6 और 8 से पूर्णतः विभाज्य हो, हमें इन 4 संख्याओं का लघुत्तम समापवर्तक ज्ञात करना होगा।&lt;/p&gt;

&lt;p&gt;4, 5, 6 और 8 के लघुत्तम समापवर्तक की गणना अभाज्य गुणनखंड द्वारा की जा सकती है;&lt;/p&gt;

&lt;p&gt;4 = 2&lt;sup&gt;2&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;5 = 5&lt;/p&gt;

&lt;p&gt;6 = 2&amp;nbsp;&amp;times; 3&amp;nbsp;&lt;/p&gt;

&lt;p&gt;8 = 2&lt;sup&gt;3&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; लघुत्तम समापवर्तक (4, 5, 6, 8) = 2&lt;sup&gt;3&lt;/sup&gt;&amp;nbsp;&amp;times; 3&amp;nbsp;&amp;times; 5 = 120&lt;/p&gt;

&lt;p&gt;4707 को 120 से विभाजित करने पर, हम प्राप्त करते हैं&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4707 = 120&amp;nbsp;&amp;times; 39 + 27&amp;nbsp;&lt;/p&gt;

&lt;p&gt;भाजक और शेषफल का अंतर जोड़ने पर (120 - 27) = 93&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4707 + 93 =&amp;nbsp;120&amp;nbsp;&amp;times; 39 + 27 + 93&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4800 = 120&amp;nbsp;&amp;times; 39 + 120&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4800 = 120 (39 + 1)&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 4800 = 120&amp;nbsp;&amp;times; 40&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4;&amp;nbsp;वह छोटी से छोटी संख्या जिसे 4707 में जोड़ा जाना चाहिए ताकि योग 4, 5, 6 और 8 से पूर्णतः विभाज्य हो, 93 है।&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;The diameters of the bases of the two cones are equal. &lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;If their slant heights are in the ratio of 3 : 4&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Concept used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;The curved surface area of a cone =&amp;nbsp;&amp;pi;rl&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;r = radius&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;l = slant height&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Since the diameters of the two cones are equal, their radius will also be the same.&amp;nbsp;&lt;/p&gt;

&lt;p&gt;Let the slant height of the two cones be&amp;nbsp;l&lt;sub&gt;1&lt;/sub&gt;&amp;nbsp;and&amp;nbsp;l&lt;sub&gt;2&lt;/sub&gt;&amp;nbsp;respectively.&lt;/p&gt;

&lt;p&gt;So,&amp;nbsp;&lt;span style=&quot;&quot;&gt;l&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;1&amp;nbsp;&lt;/span&gt;: &lt;span style=&quot;&quot;&gt;l&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 3 : 4&lt;/p&gt;

&lt;p&gt;The curved surface area of the two cones is&amp;nbsp;&amp;pi;rl₁ and &amp;pi;rl₂.&lt;/p&gt;

&lt;p&gt;So, the ratio of their curved surface area is&amp;nbsp;&amp;pi;rl&lt;sub&gt;1&lt;/sub&gt;/&amp;pi;rl&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;.&lt;/p&gt;

&lt;p&gt;&amp;pi; and r are canceled.&lt;/p&gt;

&lt;p&gt;l&lt;sub&gt;1&lt;/sub&gt;/l&lt;sub&gt;2&lt;/sub&gt; = 3/4&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; The ratio of the curved surface area of two cones is 3 : 4&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;दिया गया है:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;दो शंकुओं के आधारों के&amp;nbsp;व्यास समान हैं।&amp;nbsp; &lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;उनकी तिर्यक&amp;nbsp;ऊँचाइयों का अनुपात 3 : 4 है।&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;प्रयुक्त अवधारणा:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;शंकु का वक्र पृष्ठीय क्षेत्रफल =&amp;nbsp;&amp;pi;rl&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;r = त्रिज्या&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;l = &amp;nbsp;तिर्यक&amp;nbsp;ऊँचाई&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;गणना:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;चूँकि दोनों शंकुओं के व्यास समान हैं, इसलिए उनकी त्रिज्याएँ भी समान होगीं।&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;माना, दोनों शंकुओं की तिर्यक ऊँचाइयाँ&amp;nbsp;क्रमशः&lt;/span&gt;&amp;nbsp;l&lt;sub&gt;1&lt;/sub&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;और&amp;nbsp;&lt;/span&gt;l&lt;sub&gt;2&lt;/sub&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;हैं।&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;इसलिए&lt;/span&gt;,&amp;nbsp;&lt;span style=&quot;&quot;&gt;l&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;1&amp;nbsp;&lt;/span&gt;: &lt;span style=&quot;&quot;&gt;l&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 3 : 4&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;दो शंकुओं का वक्र पृष्ठीय क्षेत्रफल&lt;/span&gt;&amp;nbsp;&amp;pi;rl₁ &lt;span style=&quot;&quot;&gt;और&amp;nbsp;&lt;/span&gt;&amp;pi;rl₂&amp;nbsp;&lt;span style=&quot;&quot;&gt;है।&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;इसलिए, इनके वक्र पृष्ठीय क्षेत्रफलों का अनुपात&amp;nbsp;&lt;/span&gt;&amp;pi;rl&lt;sub&gt;1&lt;/sub&gt;/&amp;pi;rl&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; bottom: -0.25em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;है।&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;pi; और r रद्द हो जाते&amp;nbsp;हैं।&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;l&lt;sub&gt;1&lt;/sub&gt;/l&lt;sub&gt;2&lt;/sub&gt; = 3/4&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; &lt;span style=&quot;&quot;&gt;दोनों&amp;nbsp;शंकुओं के वक्र पृष्ठीय क्षेत्रफलों&amp;nbsp;का अनुपात 3 : 4 है।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Principal (P) = Rs. 12,000&lt;/p&gt;

&lt;p&gt;Down payment = Rs. 2,000&lt;/p&gt;

&lt;p&gt;Time (t) = 1 year&lt;/p&gt;

&lt;p&gt;Rate (r) = 10% per year&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula Used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Simple Interest (SI) = (P &amp;times; r &amp;times; t) / 100&lt;br /&gt;
&lt;br /&gt;
&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Interest will be incurred on the amount = 12000 - 2000 = 10000&lt;/p&gt;

&lt;p&gt;&amp;rArr; SI = (10,000 &amp;times; 10 &amp;times; 1) / 100&lt;/p&gt;

&lt;p&gt;&amp;rArr; SI = 1,000&lt;br /&gt;
&lt;br /&gt;
Total amount paid = Principal + SI&lt;/p&gt;

&lt;p&gt;&amp;rArr; Total amount = 12,000 + 1,000&lt;/p&gt;

&lt;p&gt;&amp;rArr; Total amount = Rs. 13,000.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; Option 2 is the correct answer.&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;दिया गया है:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;मूलधन&amp;nbsp;(P) = 12,000 रुपये&lt;/p&gt;

&lt;p&gt;अग्रिम भुगतान = 2,000&amp;nbsp;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;रुपये&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;समय&amp;nbsp;(t) = 1 वर्ष&lt;/p&gt;

&lt;p&gt;दर&amp;nbsp;(r) = 10% प्रति वर्ष&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;प्रयुक्त सूत्र:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;साधारण ब्याज&amp;nbsp;(SI) = (P &amp;times; r &amp;times; t) / 100&lt;br /&gt;
&lt;br /&gt;
&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;राशि पर ब्याज लगेगा = 12000 - 2000 = 10000&lt;/p&gt;

&lt;p&gt;&amp;rArr; SI = (10,000 &amp;times; 10 &amp;times; 1) / 100&lt;/p&gt;

&lt;p&gt;&amp;rArr; SI = 1,000&lt;/p&gt;

&lt;p&gt;भुगतान की गई कुल राशि = मूलधन + &lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;SI&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; कुल राशि = 12,000 + 1,000&lt;/p&gt;

&lt;p&gt;&amp;rArr; कुल राशि = 13,000 रुपये&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; विकल्प 2 सही उत्तर है।&lt;/strong&gt;&lt;/p&gt;

