&lt;span class=&quot;math-tex&quot;&gt;\(6x - 1500 \over 5x - 1000\)&lt;/span&gt;&amp;nbsp;=&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(7 \over 6\)&lt;/span&gt;&lt;/p&gt;

